#nullable enable

using System;
using System.Threading;
using System.Threading.Tasks;
using Npgsql;
using SaaSFoundry.EngineeringWorkbench.Core.Contracts.Transport;

namespace SaaSFoundry.Persistence.Idempotency;

public sealed class NpgsqlIdempotencyEnforcer : IIdempotencyEnforcer
{
    private readonly string _connectionString;
    private readonly TimeSpan _ttl;

    public NpgsqlIdempotencyEnforcer(string connectionString, TimeSpan ttl)
    {
        _connectionString = connectionString;
        _ttl = ttl;
    }

    public async Task<IdempotencyAcquisitionStatus> TryAcquireAsync(string tenantId, string idempotencyKey, CancellationToken cancellationToken = default)
    {
        var now = DateTimeOffset.UtcNow;
        var expiresAt = now.Add(_ttl);

        await using var connection = new NpgsqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken);

        await using var cmd = connection.CreateCommand();
        cmd.CommandText = @"
            INSERT INTO sys_idempotency_keys (tenant_id, idempotency_key, status, created_at, expires_at)
            VALUES (@TenantId, @IdempotencyKey, 'InProgress', @Now, @ExpiresAt)
            ON CONFLICT (tenant_id, idempotency_key) DO NOTHING;";
        cmd.Parameters.AddWithValue("TenantId", tenantId);
        cmd.Parameters.AddWithValue("IdempotencyKey", idempotencyKey);
        cmd.Parameters.AddWithValue("Now", now);
        cmd.Parameters.AddWithValue("ExpiresAt", expiresAt);

        var inserted = await cmd.ExecuteNonQueryAsync(cancellationToken);
        if (inserted > 0)
        {
            return IdempotencyAcquisitionStatus.Acquired;
        }

        await using var updateCmd = connection.CreateCommand();
        updateCmd.CommandText = @"
            UPDATE sys_idempotency_keys
            SET status = 'InProgress', created_at = @Now, expires_at = @ExpiresAt
            WHERE tenant_id = @TenantId AND idempotency_key = @IdempotencyKey AND status = 'InProgress' AND expires_at < @Now;";
        updateCmd.Parameters.AddWithValue("TenantId", tenantId);
        updateCmd.Parameters.AddWithValue("IdempotencyKey", idempotencyKey);
        updateCmd.Parameters.AddWithValue("Now", now);
        updateCmd.Parameters.AddWithValue("ExpiresAt", expiresAt);

        var updated = await updateCmd.ExecuteNonQueryAsync(cancellationToken);
        if (updated > 0)
        {
            return IdempotencyAcquisitionStatus.Acquired;
        }

        await using var selectCmd = connection.CreateCommand();
        selectCmd.CommandText = @"
            SELECT status FROM sys_idempotency_keys
            WHERE tenant_id = @TenantId AND idempotency_key = @IdempotencyKey;";
        selectCmd.Parameters.AddWithValue("TenantId", tenantId);
        selectCmd.Parameters.AddWithValue("IdempotencyKey", idempotencyKey);

        var statusStr = (string?)await selectCmd.ExecuteScalarAsync(cancellationToken);
        if (statusStr == "AlreadyProcessed")
        {
            return IdempotencyAcquisitionStatus.AlreadyProcessed;
        }

        return IdempotencyAcquisitionStatus.InProgress;
    }

    public async Task CompleteAsync(string tenantId, string idempotencyKey, CancellationToken cancellationToken = default)
    {
        await using var connection = new NpgsqlConnection(_connectionString);
        await connection.OpenAsync(cancellationToken);

        await using var cmd = connection.CreateCommand();
        cmd.CommandText = @"
            UPDATE sys_idempotency_keys
            SET status = 'AlreadyProcessed'
            WHERE tenant_id = @TenantId AND idempotency_key = @IdempotencyKey AND status = 'InProgress';";
        cmd.Parameters.AddWithValue("TenantId", tenantId);
        cmd.Parameters.AddWithValue("IdempotencyKey", idempotencyKey);

        await cmd.ExecuteNonQueryAsync(cancellationToken);
    }
}